effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec2 dir = uv - 0.5;
  float r = length(dir) * falloff;
  vec2 o = dir * r * amount * mixAmt;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = src.a;
  float cr = texture2DCv(inputImg.texture, uv + o).r;
  float cg = src.g;
  float cb = texture2DCv(inputImg.texture, uv - o).b;
  gl_FragColor = vec4(cr, cg, cb, a);
}
